-- Phase 10: Copilot for Human Reviewers
-- Stores AI-generated context that assists human reviewers when approving drafts.

CREATE TABLE IF NOT EXISTS copilot_context (
    id TEXT PRIMARY KEY,
    draft_id TEXT NOT NULL,
    conversation_id TEXT NOT NULL,
    contact_id TEXT NOT NULL,

    -- Conversation summary generated by Claude
    conversation_summary TEXT,

    -- Customer profile enrichment (JSON): lead info, contact details, conversation stats
    customer_profile TEXT,

    -- Suggested edits for the draft (JSON array of edit suggestions)
    suggested_edits TEXT,

    -- Key topics extracted from the conversation
    key_topics TEXT,

    -- Sentiment of the customer in the conversation
    customer_sentiment TEXT,

    -- Whether the context has been generated
    generated BOOLEAN NOT NULL DEFAULT false,

    -- When the context was last generated
    generated_at TEXT,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_copilot_context_draft ON copilot_context(draft_id);
CREATE INDEX IF NOT EXISTS idx_copilot_context_conversation ON copilot_context(conversation_id);
